const nw = msg.data.new_state;
const ow = msg.data.old_state;
if (!nw || !ow || !nw.attributes.wpisy) return null;

// 1. Pobieramy slug i nazwę ucznia
const entityId = nw.entity_id;
const studentSlug = entityId.replace('sensor.vultron_freq_', '');
const imie = nw.attributes.friendly_name.split(': ')[1] || "Dziecko";

// 2. Pobieramy plan lekcji z HA, żeby wiedzieć jaki to przedmiot
const states = global.get('homeassistant').homeAssistant.states;
const planEntity = states['sensor.vultron_plan_' + studentSlug];
const lekcje = planEntity ? planEntity.attributes.lekcje : [];

// 3. Definicja kategorii, które nas interesują
const catMap = {
    2: "Nieobecność ❌",
    3: "Nieobecność usprawiedliwiona ✅",
    4: "Spóźnienie ⚠️",
    5: "Spóźnienie usprawiedliwione ⏳",
    7: "Zwolnienie 🚪"
};

const noweWpisy = nw.attributes.wpisy;
const stareWpisy = ow.attributes.wpisy || [];

// 4. Znajdź wpisy, których nie było wcześniej
let noweAlerty = noweWpisy.filter(n => {
    // Interesują nas tylko kategorie z catMap
    if (!catMap[n.k]) return false;
    // Sprawdź czy identyczny wpis był w starym stanie
    return !stareWpisy.some(o => o.d === n.d && o.t === n.t && o.k === n.k);
});

if (noweAlerty.length > 0) {
    let powiadomienia = noweAlerty.map(a => {
        // Spróbuj dopasować przedmiot z planu po dacie i godzinie
        // n.t to np. "08:10", l.g to np. "08:10-08:55"
        const lekcja = lekcje.find(l => l.d === a.d && l.g.startsWith(a.t));
        const przedmiot = lekcja ? lekcja.p : "Lekcja";

        return `${catMap[a.k]} na lekcji: ${przedmiot} (${a.t})`;
    });

    msg.payload = {
        data: {
            title: `Alert frekwencji: ${imie}`,
            message: powiadomienia.join('\n'),
            notification_id: "vultron_alert_" + studentSlug
        }
    };
    return msg;
}

return null;
